<script setup>
import {useForm,Link} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';const props=defineProps({product:Object});const form=useForm({qty:1});const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);const add=()=>form.post(`/keranjang/${props.product.id}`);
</script>
<template><AppLayout><div class="page"><Link href="/" class="muted">← Kembali ke produk</Link><div class="grid" style="grid-template-columns:1fr 1.2fr;margin-top:22px"><div class="product-img" style="height:390px;border-radius:18px;font-size:120px">{{product.image||'📦'}}</div><div class="panel"><div class="muted">{{product.category?.name}}</div><h1 class="page-title">{{product.name}}</h1><div class="price" style="font-size:28px">{{money(product.price)}}</div><p style="line-height:1.8;color:#65718a">{{product.description}}</p><p class="muted">Stok tersedia: {{product.stock}}</p><form @submit.prevent="add"><div class="field"><label>Jumlah</label><input type="number" min="1" :max="product.stock" v-model="form.qty" style="max-width:100px"></div><button class="btn" :disabled="product.stock<1||form.processing">Tambah ke Keranjang</button><div v-if="form.errors.qty" style="color:#dc3545">{{form.errors.qty}}</div></form></div></div></div></AppLayout></template>
